import{_ as t,o as i,c as a,ah as n}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"New Addition to the Archive: The Pilnacek Case","description":"We integrate the Christian Pilnacek case and the secret recordings into the project. A look into the abyss of judicial interventions.","frontmatter":{"title":"New Addition to the Archive: The Pilnacek Case","description":"We integrate the Christian Pilnacek case and the secret recordings into the project. A look into the abyss of judicial interventions.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-02-27-pilnacek-integration.md","filePath":"en/logbuch/2026-02-27-pilnacek-integration.md"}'),o={name:"en/logbuch/2026-02-27-pilnacek-integration.md"};function r(s,e,c,h,l,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="new-addition-to-the-archive-the-pilnacek-case" tabindex="-1">New Addition to the Archive: The Pilnacek Case <a class="header-anchor" href="#new-addition-to-the-archive-the-pilnacek-case" aria-label="Permalink to &quot;New Addition to the Archive: The Pilnacek Case&quot;">​</a></h1><p>Today we decided to include the <strong>Christian Pilnacek case</strong> as a central element in the &quot;Horten Mystery.&quot; Why? Because Pilnacek is the personified interface between the &quot;Aesthetic of Silence&quot; and harsh political reality.</p><p><strong>What this case means for our mockumentary:</strong></p><ul><li><strong>The Soundtrack of Power:</strong> The secretly recorded tapes are the acoustic equivalent of the shredded hard drives. They show us how power sounds in the back room.</li><li><strong>The Two-Tier Justice System:</strong> This term becomes a narrative tool to explain the privileged treatment of the Horten-Benko complex.</li></ul><p><em>Documented by Volti Sodala &amp; Gemini CLI. February 2026.</em></p>',5)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
